class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if len(self.items) == 0:
            raise IndexError("The stack is empty")
        return self.items.pop()

    def peek(self):
        if len(self.items) == 0:
            raise IndexError("The stack is empty")
        return self.items[-1]

    def size(self):
        return len(self.items)

    def is_empty(self):
        return len(self.items) == 0
```
